  BASEURL: item['BASEURL\n（省略可）\nサイトURL'] || sc.BASEURL || '',
  FIRSTPERSON: item['FIRSTPERSON\n（省略可）\n一人称'] || sc.FIRSTPERSON || '',
  IMAGE_TRIGGER: String(item['IMAGE_TRIGGER\n（省略可）\nTRUE/FALSE'] || 'FALSE').toUpperCase(),
